const raw = $input.first().json;
const expected = $env.ANSER_WEBHOOK_TOKEN || '';
if (expected && ((raw.headers || {})['x-anser-token'] || '') !== expected) {
  return [{ json: { valid: false, error: 'Unauthorized' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const miss = [];
if (!b.batch_code) miss.push('batch_code');
if (!b.event) miss.push('event (start|stage|complete)');
if (miss.length) return [{ json: { valid: false, error: 'Missing required fields: ' + miss.join(', ') } }];
// Nguồn: cảm biến IoT (nhiệt/độ ẩm) hoặc app/tablet tại xưởng — cùng một webhook
return [{ json: { valid: true, event: String(b.event), batch_code: String(b.batch_code), request_body: JSON.stringify({ event: b.event, batch_code: b.batch_code, order_code: b.order_code || null, material_lot_code: b.material_lot_code || null, input_material_kg: b.input_material_kg || 0, shift: b.shift || null, source: b.source || 'manual', stage: b.stage || null, temp_c: b.temp_c ?? null, duration_min: b.duration_min ?? null, operator: b.operator || null, note: b.note || null, output_units: b.output_units || 0, ng_units: b.ng_units || 0, moisture_pct: b.moisture_pct ?? null, material_cost_vnd: b.material_cost_vnd || 0, labor_cost_vnd: b.labor_cost_vnd || 0 }) } }];

const d = $input.first().json;
const bc = $('Verify + Validate').first().json.batch_code;
// Chỉ notify các mốc quan trọng; log công đoạn thường (stage) chạy êm
let notify_needed = true, title = '', color = 3066993, desc = '';
switch (d.status) {
  case 'started':
    if (d.window_status === 'overdue') { title = '🔴 MẺ ' + bc + ' — NVL QUÁ CỬA SỔ 24H'; color = 15158332; desc = 'Lô nguyên liệu đã quá hạn chế biến ' + Math.abs(d.hours_left ?? 0) + 'h — nguy cơ giảm cynarin. Cân nhắc chuyển hướng sản phẩm.'; }
    else if (d.window_status === 'urgent') { title = '🟠 Bắt đầu mẻ ' + bc + ' — còn ' + d.hours_left + 'h cửa sổ 24h'; color = 15105570; desc = 'Ưu tiên chế biến liên tục, không để gián đoạn.'; }
    else { title = '🏭 Bắt đầu mẻ ' + bc; desc = d.window_status === 'ok' ? ('Trong cửa sổ 24h (còn ' + d.hours_left + 'h).') : 'Nguyên liệu khô — không ràng buộc 24h.'; }
    break;
  case 'duplicate':
    title = '🔁 Mẻ trùng batch_code (bỏ qua)'; color = 10197915; desc = 'Gateway/tablet gửi lại — không tạo trùng.';
    break;
  case 'moisture_fail':
    title = '🟠 Mẻ ' + bc + ' — độ ẩm ' + d.moisture_pct + '% CHƯA ĐẠT'; color = 15105570; desc = 'Vượt ngưỡng ' + d.max_allowed + '% → nguy cơ nấm mốc. **Sấy tiếp rồi đo lại** — mẻ chưa được chốt.';
    break;
  case 'completed':
    title = '🟢 Mẻ ' + bc + ' hoàn thành — độ ẩm ' + d.moisture_pct + '%, HSD ' + d.shelf_months + ' tháng';
    desc = 'HSD: **' + d.expiry_date + '** (độ ẩm quyết định). Trạng thái: chờ kiểm nghiệm dược liệu (F2) — CHƯA mở bán.';
    break;
  default:
    notify_needed = false; // 'logged' — ghi công đoạn thường
}
const notify_body = JSON.stringify({ channel: 'discord', title, color, description: desc });
const resp = JSON.stringify(d);
return [{ json: { notify_needed, notify_body, resp } }];
